const brandLines=['A good outfit starts with how it feels.','A crew neck that slips under your jacket.','A deep plunge beneath your favourite dress.','A shade of brown that catches the light.','These are the pieces we reach for,','from the first layer to the finishing touch.','Explore everyday shapes in HoneyHaus Closet,','then find your signature look in Hair.','Wear each piece your own way.','There is room for both sides of you here.'];
function ribbon(words,icons=['star','closet','hair','zip']){const group='<div>'+words.map((w,i)=>'<span>'+ico(icons[i%icons.length])+w+'</span>').join('')+'</div>';return '<div class="ribbon" aria-hidden="true"><div class="ribbon-belt">'+group+group+group+group+'</div></div>'}
const journalEntries=[['The crew neckline','A high, clean neckline sits neatly under an open shirt.','long'],['From the side','A closer look at the cut of the long sleeve.','long'],['A front fastening','A front zip runs down the centre of this sculpting one-piece.','zip'],['Chocolate tones','Wear brown as the starting point for a tonal outfit.','plunge'],['The low neckline','The Plunge bodyshaper follows the line of a deeper neckline.','plunge'],['The final detail','Finish a simple silhouette with a softly defined side part.','bob']];
function journal(){return `<section class="journal"><div class="journal-title"><h2>10,000+ 5-star reviews</h2><div><button data-rail="-1" aria-label="Previous reviews">‹</button><button data-rail="1" aria-label="Next reviews">›</button></div></div><div class="journal-track">${journalEntries.map(([t,d,id],i)=>`<a href="#product/${id}">${i%2?img(arts+'atelier-'+(i+1)+'.webp',''):ico(['closet','fit','zip','star','fit','hair'][i])}<span class="review-stars">★★★★★</span><h3>${t}</h3><p>${d}</p><small>${['Maryam O.','Daphne N.','Bisan T.','Charlie L.','Nico K.','Alex D.'][i]}</small></a>`).join('')}</div></section>`}
const rituals=[['Begin with the base','Crew Neck Bodysuit','Choose Black for a crisp contrast or Brown for a tonal outfit.','long','long-brown'],['Choose your shape','Zipper Shapewear','Explore the front zip and shorts-length cut.','zip','zip-back'],['Find your neckline','Plunge Bodyshaper','Pair the deep V with an open neckline.','plunge','plunge'],['Finish with Hair','The Signature Bob','Frame the look with a sleek side part.','bob','hair']];
function ritual(){return `<section class="dressing"><div><small>THE DRESSING ROOM</small><h2>One look.<br><em>Four steps.</em></h2>${rituals.map(([t,p,d,id],i)=>`<details name="ritual" data-step="${i}" ${i?'':'open'}><summary><small>0${i+1}</small> ${t}</summary><p>${p}<br>${d} <a href="#product/${id}">View piece</a></p></details>`).join('')}</div><figure><img id="step-photo" src="assets/long-brown.webp" alt="Crew Neck Bodysuit"><figcaption id="step-cap">Crew Neck Bodysuit</figcaption></figure></section>`}
function world(){return `<section class="world">${Array.from({length:8},(_,i)=>img(arts+'atelier-'+(i+1)+'.webp','')).join('')}<div>${ico('star')}<h2>Inside the world of HoneyHaus.</h2><p>Fabric, form and the details in between.</p>${cta('collections','Explore the collections')}</div></section>`}
function floatingStory(){return `<section class="floatstory">${[1,2,3].map(i=>img(arts+'story-'+i+'.webp','')).join('')}<div><small>ABOUT US</small><h2>Our wardrobe starts with <em>everyday essentials.</em> Our hair brings the finishing touch. Together, they are <em>HoneyHaus.</em></h2>${cta('about','More about us')}</div></section>`}
document.addEventListener('toggle',e=>{let i=e.target.dataset?.step;if(i===undefined||!e.target.open)return;let [,p,,,f]=rituals[i],photo=document.querySelector('#step-photo');if(photo){photo.src=f==='hair'?'hair.webp':arts+f+'.webp';photo.alt=p;document.querySelector('#step-cap').textContent=p}},true);
document.addEventListener('click',e=>{let b=e.target.closest('[data-rail]');if(b){let row=document.querySelector('.journal-track');row.scrollBy({left:Number(b.dataset.rail)*row.firstElementChild.offsetWidth,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})}if(e.target.closest('[data-up]'))window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});if(e.target.closest('[data-motion]')){let b=e.target.closest('[data-motion]'),on=document.body.classList.toggle('motion-paused');b.setAttribute('aria-pressed',on);b.textContent=on?'Resume motion':'Pause motion'}});
const syncMast=()=>document.body.classList.toggle('scrolled',scrollY>28);
window.addEventListener('scroll',syncMast,{passive:true});window.addEventListener('pageshow',syncMast);syncMast();
function silhouette(id){
 const forms={closet:'M18 5l8-3q6 7 12 0l8 3 12 29-7 3-11-20-1 21-7 8-7-8-1-21-11 20-7-3z',zip:'M22 3h3l1 8q6 6 12 0l1-8h3l1 15-3 9 5 18H33l-1-9-1 9H19l5-18-3-9z',fit:'M22 3h4l6 14 6-14h4l-1 16-3 8 5 17H33l-1-6-1 6H21l5-17-3-8z',hair:'M12 39c4-5 0-17 5-26 8-18 33-13 35 6l2 22-11 1-3-25c-6 9-13 10-17 15l-1 11z'};
 return '<svg viewBox="0 0 64 48" aria-hidden="true" class="cut-icon"><path fill="currentColor" d="'+forms[id]+'"/></svg>'
}
